// F4 — the frozen v2 surface matrix.
//
// This module is the single, immutable inventory the foundation, all nine
// parallel route tickets (R1…R7) and G1 verify against. It is COMPLETE the
// moment F4 lands: seventeen rows — thirteen shipped product routes and four
// harness routes — each naming its ticket owner, canonical prototype,
// deterministic seed strategy, readiness descriptor, semantic checks, axe
// exceptions and immutable static file-owner set.
//
// Route tickets do NOT edit this file. They do not add rows, retune a seed,
// widen a file-owner set, or flip a flag; there is no migration ledger and no
// `test.skip`. Owner selection (see `v2-owner-selection.ts`) filters these rows
// BEFORE Playwright declares a test, so `pnpm test:e2e` at F4 registers only the
// foundation row and carries no hidden route debt. If a descriptor here turns
// out to be wrong, F4 is reopened and repaired serially — that cost is the point
// of freezing it, not an accident of it.
//
// Everything here is plain data with no Playwright runtime import, so the
// focused unit tests next door can exercise it in the node vitest environment.

// ---------------------------------------------------------------------------
// Owners
// ---------------------------------------------------------------------------

/** Every ticket that owns at least one row. R2a/R2b/R2c stay distinct values. */
export const V2_OWNERS = [
  "foundation",
  "R1",
  "R2a",
  "R2b",
  "R2c",
  "R3",
  "R4",
  "R5",
  "R6",
  "R7",
] as const;

export type V2Owner = (typeof V2_OWNERS)[number];

/** The accepted `V2_MATRIX_OWNER` / `V2_STYLE_OWNER` vocabulary. */
export const V2_SELECTORS = [...V2_OWNERS, "all"] as const;

export type V2Selector = (typeof V2_SELECTORS)[number];

// ---------------------------------------------------------------------------
// Seed and readiness vocabulary
// ---------------------------------------------------------------------------

/**
 * Named deterministic seed strategies. Every builder produces byte-stable
 * identifiers and dates (see `v2-seed.ts`) — no clock, no randomness, no
 * dependency on another row having run first.
 */
export const V2_SEED_KEYS = [
  /** Reset only. The row's surface needs no scenario data. */
  "empty",
  /** One roster week: range, staff + group, shift types + group, date group. */
  "roster-week",
  /** `roster-week` plus the guided-rule source constraints. */
  "roster-week-rules",
  /** `roster-week` plus one card of every constraint kind. */
  "roster-week-constraints",
  /** `roster-week` plus leave / request / off matrix cells. */
  "roster-week-requests",
  /** `roster-week` recorded as a current Workspace backup, then edited stale. */
  "roster-week-backup",
  /** The minimum required data that enables an Optimize run. */
  "optimize-ready",
  /** Reset only: the harness page seeds its own deterministic state. */
  "harness-self-seeded",
] as const;

export type V2SeedKey = (typeof V2_SEED_KEYS)[number];

/**
 * Named readiness strategies. `app-shell` waits out the real T04 hydration
 * lifecycle behind `HydrationGate`; `bare` is for the routes that render outside
 * the `(app)` group and therefore have no gate to wait on. Both then wait for
 * the row's own marker, `document.fonts.ready`, settled portals and a stable
 * animation frame. A fixed sleep is never a correctness signal.
 */
export const V2_READINESS_STRATEGIES = ["app-shell", "bare"] as const;

export type V2ReadinessStrategy = (typeof V2_READINESS_STRATEGIES)[number];

/** The app-mode preference a direct visit must adopt before the validity gate runs. */
export type V2RouteMode = "guided" | "advanced" | null;

export interface V2ReadinessDescriptor {
  readonly strategy: V2ReadinessStrategy;
  /**
   * The row's EXISTING screen/fixture marker — a selector that already exists in
   * the shipped source today. F4 invents no new product markers.
   */
  readonly marker: string;
  /**
   * `advanced` for the DL12 §2 Advanced-only routes, whose direct visit would
   * otherwise be bounced to Home by `useRouteValidityGate` once the stored
   * preference adopts. `null` where the route carries no mode policy at all.
   */
  readonly mode: V2RouteMode;
  /** Whether the row needs the `window.__nsStore` seam (test-bridge.tsx). */
  readonly storeSeam: boolean;
}

// ---------------------------------------------------------------------------
// Semantic checks
// ---------------------------------------------------------------------------

/**
 * The closed surface-recipe vocabulary (v2 technical plan, "Surface recipe").
 * The runtime runner resolves each role to its expected tone token and elevation
 * through `V2_ROLE_CONTRACT` below, so a row declares the ROLE it means rather
 * than restating a token — the same indirection the recipe itself uses.
 */
export const V2_SURFACE_ROLES = [
  "page",
  "surface",
  "selected",
  "drop-target",
  "raised",
  "drawer",
  "well",
  "band",
  "zebra",
  "sticky",
] as const;

export type V2SurfaceRole = (typeof V2_SURFACE_ROLES)[number];

export interface V2RoleContract {
  /** The runtime tone variable the role's background must resolve to. */
  readonly tone: string;
  /** `outer` — a drop shadow; `inset` — an inset well; `none` — flat. */
  readonly elevation: "outer" | "inset" | "none";
}

/**
 * Role → tone/elevation, straight from the technical plan's recipe table. A well
 * never takes an outer shadow and a raised surface never takes an inset one
 * (DESIGN.md §4 rule 1), which is why elevation is part of the contract and not
 * a free choice of the consumer.
 */
export const V2_ROLE_CONTRACT: Readonly<Record<V2SurfaceRole, V2RoleContract>> = Object.freeze({
  page: { tone: "--bg", elevation: "none" },
  surface: { tone: "--surface", elevation: "outer" },
  selected: { tone: "--surface", elevation: "outer" },
  "drop-target": { tone: "--panel-alt", elevation: "outer" },
  raised: { tone: "--surface2", elevation: "outer" },
  drawer: { tone: "--sidebar", elevation: "outer" },
  well: { tone: "--panel", elevation: "inset" },
  band: { tone: "--panel", elevation: "none" },
  zebra: { tone: "--panel-alt", elevation: "none" },
  sticky: { tone: "--surface", elevation: "outer" },
});

/** Radius roles. `square` is the explicit data-surface treatment, not an absence. */
export const V2_RADIUS_ROLES = ["card", "control", "chip", "pill", "square"] as const;

export type V2RadiusRole = (typeof V2_RADIUS_ROLES)[number];

/** Role → the exact px Chromium must compute. Absolute; never multiplied by 0.9. */
export const V2_RADIUS_CONTRACT: Readonly<Record<V2RadiusRole, string>> = Object.freeze({
  card: "16px",
  control: "12px",
  chip: "9px",
  pill: "999px",
  square: "0px",
});

/**
 * One declared expectation about one selector. `role` and `radius` are
 * independently optional because they are independent contracts: DESIGN.md §5
 * is explicit that radius is NOT inferred from tone, so a specimen may pin its
 * geometry without claiming a surface role (the radius specimens are a plain
 * bordered box whose only contract is the corner) and a role may be pinned
 * without geometry (the owner chooses that). At least one must be present,
 * which `v2-surface-matrix.test.ts` asserts for every row.
 */
export interface V2SemanticCheck {
  /** Human label used verbatim in the failure diagnostic. */
  readonly label: string;
  /** A selector resolved inside the loaded route. */
  readonly selector: string;
  readonly role?: V2SurfaceRole;
  /** Declared only where geometry is part of THIS owner's contract. */
  readonly radius?: V2RadiusRole;
  /** The check must match at least this many elements (default 1). */
  readonly minCount?: number;
}

// ---------------------------------------------------------------------------
// Axe exceptions
// ---------------------------------------------------------------------------

/**
 * One rule, one exact element, one reason. There is deliberately no shape here
 * that can express "disable colour-contrast" or "exclude this route": an
 * exception names a single axe rule id AND a single selector, and the runner
 * filters violation NODES rather than switching the rule off, so any other node
 * that breaks the same rule still fails. G1 re-evaluates every entry.
 */
export interface V2AxeException {
  readonly rule: string;
  readonly selector: string;
  readonly reason: string;
}

// ---------------------------------------------------------------------------
// Rows
// ---------------------------------------------------------------------------

export interface V2Row {
  readonly route: string;
  readonly kind: "product" | "harness";
  readonly owner: V2Owner;
  /**
   * The canonical prototype screen this route is judged against (repo-relative),
   * or `HARNESS_NO_PROTOTYPE` for a test harness with no product prototype.
   */
  readonly prototype: string;
  readonly seed: V2SeedKey;
  readonly readiness: V2ReadinessDescriptor;
  readonly semanticChecks: readonly V2SemanticCheck[];
  readonly axeExceptions: readonly V2AxeException[];
}

/** The literal a harness row records instead of naming a prototype screen. */
export const HARNESS_NO_PROTOTYPE = "harness/no product prototype";

const PROTOTYPE_DIR = "docs/design_prototype/source";

/** The `(app)`-group screen marker every product route already renders today. */
const SCREEN_MARKER = '[data-testid="screen"]';

function appShell(marker: string, mode: Exclude<V2RouteMode, null>): V2ReadinessDescriptor {
  return Object.freeze({ strategy: "app-shell", marker, mode, storeSeam: true });
}

function bare(marker: string): V2ReadinessDescriptor {
  return Object.freeze({ strategy: "bare", marker, mode: null, storeSeam: false });
}

