/** The frozen manifest. Deep-frozen so a spec cannot mutate a row in place. */
export const V2_SURFACE_MATRIX: readonly V2Row[] = Object.freeze(
  ROWS.map((row) =>
    Object.freeze({
      ...row,
      readiness: Object.freeze({ ...row.readiness }),
      semanticChecks: Object.freeze(row.semanticChecks.map((c) => Object.freeze({ ...c }))),
      axeExceptions: Object.freeze(row.axeExceptions.map((e) => Object.freeze({ ...e }))),
    }),
  ),
);

/** The thirteen shipped product routes, in manifest order. */
export const V2_PRODUCT_ROUTES: readonly string[] = Object.freeze(
  V2_SURFACE_MATRIX.filter((r) => r.kind === "product").map((r) => r.route),
);

/** The four harness routes, in manifest order. */
export const V2_HARNESS_ROUTES: readonly string[] = Object.freeze(
  V2_SURFACE_MATRIX.filter((r) => r.kind === "harness").map((r) => r.route),
);

// ---------------------------------------------------------------------------
// Immutable static file ownership
// ---------------------------------------------------------------------------

/**
 * The presentation-bearing source each owner may author, as `web/`-relative glob
 * patterns. This is the set `V2_STYLE_OWNER` selects for the static provenance
 * scanner, and it is also the ownership map the parallel wave depends on: two
 * tickets that could both touch one file could both break it, and neither review
 * would see the other's change.
 *
 * The sets are exhaustive over the app's presentation sources and provably
 * disjoint — both properties are asserted in `v2-surface-matrix.test.ts` against
 * what is actually on disk, so a new component cannot be added without being
 * given an owner.
 */
export const V2_STYLE_OWNER_FILES: Readonly<Record<V2Owner, readonly string[]>> = Object.freeze({
  // The value authority plus every shared primitive, theme control and shared
  // entity-editor presenter migrated once by F1–F3 ahead of its route consumers.
  //
  // The entity-editor presenters are enumerated by FAMILY rather than swept with
  // `components/entity-editor/**/*.tsx`, because exactly one file in that
  // directory is NOT foundation-owned: `working-time-fields.tsx` belongs to R2c
  // (see the R2c entry below). The glob grammar here is deliberately tiny — `**`
  // and `*`, no negation — so an exception is expressed by naming what IS owned,
  // not by subtracting from a sweep. The consequence is intended: a NEW
  // entity-editor presenter matches no owner and fails the "every presentation
  // source has exactly one owner" gate until it is assigned, which is the
  // fail-closed behaviour this map exists for.
  foundation: Object.freeze([
    "app/globals.css",
    "app/layout.tsx",
    "app/providers.tsx",
    "app/design-system/page.tsx",
    "components/ui/**/*.tsx",
    "components/theme/**/*.tsx",
    "components/entity-editor/groups-section*.tsx",
    "components/entity-editor/transfer-list*.tsx",
    "components/icons.tsx",
    "components/app-version.tsx",
  ]),
  R1: Object.freeze([
    "app/(app)/layout.tsx",
    "app/(app)/page.tsx",
    "components/shell/**/*.tsx",
    "components/home/**/*.tsx",
  ]),
  // The FullCalendar override sheet is presentation-bearing CSS and belongs to
  // the Dates owner like the rest of that screen — it is the second stylesheet
  // in the app, and the only one outside the foundation.
  R2a: Object.freeze([
    "app/(app)/dates/page.tsx",
    "components/dates/**/*.tsx",
    "components/dates/calendar.css",
  ]),
  R2b: Object.freeze(["app/(app)/people/page.tsx", "components/people/**/*.tsx"]),
  // `working-time-fields` is the one entity-editor presenter that is NOT
  // foundation-owned. Shift Types is its only live UI consumer, so the R2c
  // ticket is authoritative that R2c is its sole visual owner — and the static
  // scan has to agree, or `V2_STYLE_OWNER=R2c` silently skips a file R2c
  // changed. Named as exact paths, never a `working-time-fields*` sweep: an
  // exception should not be able to widen itself.
  R2c: Object.freeze([
    "app/(app)/shift-types/page.tsx",
    "components/shift-types/**/*.tsx",
    "components/entity-editor/working-time-fields.tsx",
    "components/entity-editor/working-time-fields.test.tsx",
  ]),
  R3: Object.freeze(["app/(app)/rules/page.tsx", "components/guided-rules/**/*.tsx"]),
  R4: Object.freeze([
    "app/(app)/shift-type-requirements/page.tsx",
    "app/(app)/shift-type-successions/page.tsx",
    "app/(app)/shift-counts/page.tsx",
    "app/(app)/shift-affinities/page.tsx",
    "app/(app)/shift-type-coverings/page.tsx",
    "components/card-editor/**/*.tsx",
    "components/requirements/**/*.tsx",
    "components/successions/**/*.tsx",
    "components/counts/**/*.tsx",
    "components/affinities/**/*.tsx",
    "components/coverings/**/*.tsx",
  ]),
  R5: Object.freeze(["app/(app)/shift-requests/page.tsx", "components/requests/**/*.tsx"]),
  R6: Object.freeze([
    "app/(app)/optimize-and-export/page.tsx",
    "app/(app)/optimize-durable-fixture/**/*.tsx",
    "app/optimize-screen-fixture/**/*.tsx",
    "app/progress-chart-fixture/**/*.tsx",
    "components/optimize/**/*.tsx",
  ]),
  R7: Object.freeze(["app/(app)/save-and-load/page.tsx", "components/save-load/**/*.tsx"]),
});

// ---------------------------------------------------------------------------
// Lookups
// ---------------------------------------------------------------------------

/** Every row owned by `owner`. */
export function rowsForOwner(owner: V2Owner): readonly V2Row[] {
  return V2_SURFACE_MATRIX.filter((row) => row.owner === owner);
}

/** The row for an exact route, or undefined. Routes are unique across the matrix. */
export function rowForRoute(route: string): V2Row | undefined {
  return V2_SURFACE_MATRIX.find((row) => row.route === route);
}

/** A compact inventory string, used verbatim in configuration-failure messages. */
export function manifestInventory(): string {
  return V2_OWNERS.map(
    (owner) =>
      `${owner}: ${
        rowsForOwner(owner)
          .map((r) => r.route)
          .join(", ") || "(none)"
      }`,
  ).join(" | ");
}
